pub fn is_non_prime(n: u64) -> bool {
    // Assumption: n >= 2
    if n <= 3 {
        return false; // 2 and 3 are prime
    }

    // If n has any divisor k in [2, n-1], it also has one with k <= sqrt(n).
    let mut k: u64 = 2;
    while k <= n / k {
        if n % k == 0 {
            return true;
        }
        k += 1;
    }
    false
}